inline MutationValues Person::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("platform_id", r), generated_detail::encode(r, platform_id_));
    values.fields.emplace(String("name", r), generated_detail::encode(r, name_));
    values.fields.emplace(String("status_id", r), generated_detail::encode(r, status_id_));
    values.fields.emplace(String("phase", r), generated_detail::encode(r, phase_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (platform_) {
        values.fields.emplace(String("platform", r),
                              Value(r, std::move(*platform_).into_values().fields));
    }
    if (status_) {
        values.fields.emplace(String("status", r),
                              Value(r, std::move(*status_).into_values().fields));
    }
    inject_runtime(values);
    return values;
}

inline Person& Person::updatePlatform(const Platform& value) {
    platform_ = detail::make_box<Platform>(memory_resource(), value);
    updatePlatformId(value.id());
    return *this;
}

inline Person& Person::updateStatus(const OrderStatus& value) {
    status_ = detail::make_box<OrderStatus>(memory_resource(), value);
    updateStatusId(value.id());
    return *this;
}
